content.content:
1	package nexusfixture
2	
3	import (
4		"bytes"
5		"fmt"
6		"net/http"
7		"net/textproto"
8		"regexp"
9		"sort"
10		"strconv"
11		"strings"
12		"time"
13	)
14	
15	// Identity is the account a fixture was recorded as; it comes from the file
16	// name suffix only.
17	type Identity string
18	
19	// The identities of the NX-03 bench.
20	const (
21		Admin     Identity = "admin"
22		Pull      Identity = "pull"
23		Anonymous Identity = "anon"
24	)
25	
26	// RecordPending marks a request-only fixture that the recorder has yet to fill.
27	const RecordPending = "pending"
28	
29	const (
30		fileSuffix    = ".http"
31		identitySep   = "--"
32		exchangeSep   = "###"
33		httpVersion   = "HTTP/1.1"
34		stubEmpty     = "<empty body>"
35		stubHTMLStart = "<HTML body omitted:"
36	)
37	
38	// Meta is the commented header of a fixture. Free text is kept raw so that
39	// Format loses nothing.
40	type Meta struct {
41		Scenario     string
42		NexusVersion string // first token of the nexus header
43		Edition      string // second token of the nexus header
44		NexusNote    string // the text in parentheses after the edition, without them
45		Measured     string // raw value: a date, optionally followed by ", free text"
46		Account      string
47		Redacted     string
48		State        string // "" = nominal
49		Record       string // "" = replay, "replay", "pending" or "skip: <reason>"
50		RecordedBy   string // "" for an imported NX-03 file
51	}
52	
53	// Exchange is one request and its answer. A request-only exchange (a pending
54	// fixture) has Status 0 and no response part.
55	type Exchange struct {
56		Method, Target, Host string // Target = path + raw query as recorded
57		RequestHeader        http.Header
58		Status               int
59		Reason               string      // reason phrase as recorded; http.StatusText when empty
60		Header               http.Header // response, whitelisted
61		Body                 []byte      // verbatim; nil when Stub != ""
62		Stub                 string      // "<empty body>" or the HTML summary, as written
63	}
64	
65	// Fixture is one file: a header and one or more exchanges.
66	type Fixture struct {
67		Campaign, Name, Scenario string // Name is the file name without ".http"
68		Identity                 Identity
69		Meta                     Meta
70		Exchanges                []Exchange
71	}
72	
73	var (
74		versionPattern = regexp.MustCompile(`^\d+(\.\d+)+(-[0-9A-Za-z.]+)?$`)
75	
76		requiredHeaders = []string{"scenario", "nexus", "measured", "account", "redacted"}
77		optionalHeaders = []string{"state", "record", "recorded-by"}
78	
79		requestOrder  = []string{"Authorization", "Accept"}
80		responseOrder = []string{
81			"Server", "Docker-Distribution-Api-Version", "Www-Authenticate", "Location", "Link",
82			"Docker-Content-Digest", "Content-Type", "Content-Length",
83		}
84		// displayNames are the header names whose written form is not the
85		// canonical one Go uses as a map key.
86		displayNames = map[string]string{"Www-Authenticate": "WWW-Authenticate"}
87	)
88	
89	func parseErr(fileName, format string, args ...any) error {
90		return fmt.Errorf("nexusfixture: %s: %s", fileName, fmt.Sprintf(format, args...))
91	}
92	
93	// Parse reads one fixture file. fileName is the base name, with ".http".
94	func Parse(campaign, fileName string, data []byte) (Fixture, error) {
95		f := Fixture{Campaign: campaign}
96		name, ok := strings.CutSuffix(fileName, fileSuffix)
97		if !ok {
98			return f, parseErr(fileName, "the file name must end in %s", fileSuffix)
99		}
100		f.Name = name
101		i := strings.LastIndex(name, identitySep)
102		if i < 0 {
103			return f, parseErr(fileName, "no identity suffix, want --admin, --pull or --anon")
104		}
105		f.Scenario, f.Identity = name[:i], Identity(name[i+len(identitySep):])
106		switch f.Identity {
107		case Admin, Pull, Anonymous:
108		default:
109			return f, parseErr(fileName, "unknown identity suffix %q, want admin, pull or anon", string(f.Identity))
110		}
111	
112		meta, rest, err := parseMeta(string(data))
113		if err != nil {
114			return f, parseErr(fileName, "%v", err)
115		}
116		f.Meta = meta
117	
118		chunks := splitExchanges(rest)
119		for n, chunk := range chunks {
120			ex, err := parseExchange(chunk, meta.Record == RecordPending)
121			if err != nil {
122				if len(chunks) > 1 {
123					return f, parseErr(fileName, "exchange %d: %v", n+1, err)
124				}
125				return f, parseErr(fileName, "%v", err)
126			}
127			f.Exchanges = append(f.Exchanges, ex)
128		}
129		return f, nil
130	}
131	
132	// nextLine cuts the first line of s; ok is false when s is empty.
133	func nextLine(s string) (line, rest string, ok bool) {
134		if s == "" {
135			return "", "", false
136		}
137		line, rest, _ = strings.Cut(s, "\n")
138		return line, rest, true
139	}
140	
141	// parseMeta reads the "# key: value" lines and the blank line after them.
142	func parseMeta(text string) (Meta, string, error) {
143		raw := map[string]string{}
144		for strings.HasPrefix(text, "#") {
145			var line string
146			line, text, _ = nextLine(text)
147			body, ok := strings.CutPrefix(line, "# ")
148			if !ok {
149				return Meta{}, "", fmt.Errorf("malformed header line, want \"# key: value\"")
150			}
151			key, value, _ := strings.Cut(body, ":")
152			if !isKnownHeader(key) {
153				return Meta{}, "", fmt.Errorf("unknown header %q", key)
154			}
155			if _, dup := raw[key]; dup {
156				return Meta{}, "", fmt.Errorf("header %q given twice", key)
157			}
158			raw[key] = strings.TrimSpace(value)
159		}
160		for _, key := range requiredHeaders {
161			if raw[key] == "" {
162				return Meta{}, "", fmt.Errorf("missing %s header", key)
163			}
164		}
165		m := Meta{
166			Scenario: raw["scenario"], Measured: raw["measured"], Account: raw["account"], Redacted: raw["redacted"],
167			State: raw["state"], Record: raw["record"], RecordedBy: raw["recorded-by"],
168		}
169		if err := parseNexus(&m, raw["nexus"]); err != nil {
170			return Meta{}, "", err
171		}
172		if err := checkMeasured(m.Measured); err != nil {
173			return Meta{}, "", err
174		}
175		if err := checkRecord(m.Record); err != nil {
176			return Meta{}, "", err
177		}
178		line, rest, ok := nextLine(text)
179		if !ok || line != "" {
180			return Meta{}, "", fmt.Errorf("a blank line must separate the headers from the request")
181		}
182		return m, rest, nil
183	}
184	
185	func isKnownHeader(key string) bool {
186		for _, k := range requiredHeaders {
187			if k == key {
188				return true
189			}
190		}
191		for _, k := range optionalHeaders {
192			if k == key {
193				return true
194			}
195		}
196		return false
197	}
198	
199	// parseNexus reads "<version> <EDITION> [(free text)]".
200	func parseNexus(m *Meta, v string) error {
201		version, rest, _ := strings.Cut(v, " ")
202		edition, rest, _ := strings.Cut(strings.TrimSpace(rest), " ")
203		rest = strings.TrimSpace(rest)
204		if !versionPattern.MatchString(version) {
205			return fmt.Errorf("nexus header: %q is not a version", version)
206		}
207		if edition == "" {
208			return fmt.Errorf("nexus header: the edition is missing after the version")
209		}
210		m.NexusVersion, m.Edition = version, edition
211		if rest == "" {
212			return nil
213		}
214		inner, ok := strings.CutPrefix(rest, "(")
215		if ok {
216			inner, ok = strings.CutSuffix(inner, ")")
217		}
218		if !ok {
219			return fmt.Errorf("nexus header: the text after the edition must be in parentheses")
220		}
221		m.NexusNote = inner
222		return nil
223	}
224	
225	func checkMeasured(v string) error {
226		if len(v) < len("2006-01-02") {
227			return fmt.Errorf("measured header: %q does not start with a YYYY-MM-DD date", v)
228		}
229		if _, err := time.Parse("2006-01-02", v[:10]); err != nil {
230			return fmt.Errorf("measured header: does not start with a YYYY-MM-DD date")
231		}
232		if after := v[10:]; after != "" && !strings.HasPrefix(after, ",") {
233			return fmt.Errorf("measured header: the date may only be followed by \", free text\"")
234		}
235		return nil
236	}
237	
238	func checkRecord(v string) error {
239		if v == "" || v == "replay" || v == RecordPending || strings.HasPrefix(v, "skip:") {
240			return nil
241		}
242		return fmt.Errorf("record header: %q is not replay, pending or skip: <reason>", v)
243	}
244	
245	// splitExchanges cuts the text after the header at each "###" line.
246	func splitExchanges(text string) []string {
247		parts := strings.Split(text, "\n"+exchangeSep+"\n")
248		for i := 0; i < len(parts)-1; i++ {
249			parts[i] += "\n" // the line break the separator consumed
250		}
251		return parts
252	}
253	
254	func parseExchange(text string, pending bool) (Exchange, error) {
255		var ex Exchange
256		line, text, _ := nextLine(text)
257		fields := strings.Fields(line)
258		if len(fields) != 3 || fields[2] != httpVersion {
259			return ex, fmt.Errorf("request line must be \"METHOD target %s\"", httpVersion)
260		}
261		ex.Method, ex.Target = fields[0], fields[1]
262	
263		header, text, blank, err := readHeaders(text)
264		if err != nil {
265			return ex, fmt.Errorf("request: %w", err)
266		}
267		ex.Host = header.Get("Host")
268		header.Del("Host")
269		ex.RequestHeader = header
270		if ex.Host == "" {
271			return ex, fmt.Errorf("the request has no Host header")
272		}
273	
274		if !blank || text == "" {
275			if pending {
276				return ex, nil
277			}
278			return ex, fmt.Errorf("the response is missing (only a pending fixture may hold a request alone)")
279		}
280		if pending {
281			return ex, fmt.Errorf("a pending fixture must not carry a response")
282		}
283		return ex, parseResponse(&ex, text)
284	}
285	
286	func parseResponse(ex *Exchange, text string) error {
287		line, text, _ := nextLine(text)
288		rest, ok := strings.CutPrefix(line, httpVersion+" ")
289		if !ok {
290			return fmt.Errorf("status line must be \"%s <code> <reason>\"", httpVersion)
291		}
292		code, reason, _ := strings.Cut(rest, " ")
293		status, err := strconv.Atoi(code)
294		if err != nil || status < 100 || status > 599 {
295			return fmt.Errorf("status code is not a number from 100 to 599")
296		}
297		ex.Status, ex.Reason = status, reason
298	
299		header, text, blank, err := readHeaders(text)
300		if err != nil {
301			return fmt.Errorf("response: %w", err)
302		}
303		if !blank {
304			return fmt.Errorf("a blank line must separate the response headers from the body")
305		}
306		ex.Header = header
307	
308		body := strings.TrimSuffix(text, "\n")
309		if body == stubEmpty || (strings.HasPrefix(body, stubHTMLStart) && strings.HasSuffix(body, ">")) {
310			ex.Stub = body
311		} else {
312			ex.Body = []byte(body)
313		}
314		return nil
315	}
316	
317	// readHeaders reads "Name: value" lines up to a blank line. blank is false when
318	// the text ended first.
319	func readHeaders(text string) (h http.Header, rest string, blank bool, err error) {
320		h = http.Header{}
321		for {
322			var line string
323			var ok bool
324			line, text, ok = nextLine(text)
325			switch {
326			case !ok:
327				return h, "", false, nil
328			case line == "":
329				return h, text, true, nil
330			case strings.HasPrefix(line, "HTTP/"):
331				return nil, "", false, fmt.Errorf("a blank line must separate the request from the response")
332			}
333			name, value, found := strings.Cut(line, ":")
334			if !found || name == "" {
335				return nil, "", false, fmt.Errorf("malformed header line, want \"Name: value\"")
336			}
337			h.Add(textproto.CanonicalMIMEHeaderKey(name), strings.TrimPrefix(value, " "))
338		}
339	}
340	
341	// Format writes a fixture in the file format; Format(Parse(b)) == b for a file
342	// the recorder or the NX-03 import wrote.
343	func Format(f Fixture) []byte {
344		var b bytes.Buffer
345		writeMeta(&b, f.Meta)
346		for i, ex := range f.Exchanges {
347			if i == 0 {
348				b.WriteString("\n")
349			} else {
350				b.WriteString(exchangeSep + "\n")
351			}
352			writeExchange(&b, ex)
353		}
354		return b.Bytes()
355	}
356	
357	func writeMeta(b *bytes.Buffer, m Meta) {
358		nexus := m.NexusVersion + " " + m.Edition
359		if m.NexusNote != "" {
360			nexus += " (" + m.NexusNote + ")"
361		}
362		lines := []struct{ key, value string }{
363			{"scenario", m.Scenario}, {"nexus", nexus}, {"measured", m.Measured},
364			{"account", m.Account}, {"redacted", m.Redacted},
365		}
366		for _, l := range lines {
367			fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
368		}
369		for _, l := range []struct{ key, value string }{{"state", m.State}, {"record", m.Record}, {"recorded-by", m.RecordedBy}} {
370			if l.value != "" {
371				fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
372			}
373		}
374	}
375	
376	func writeExchange(b *bytes.Buffer, ex Exchange) {
377		fmt.Fprintf(b, "%s %s %s\nHost: %s\n", ex.Method, ex.Target, httpVersion, ex.Host)
378		writeHeaders(b, ex.RequestHeader, requestOrder, "Host")
379		if ex.Status == 0 {
380			return
381		}
382		reason := ex.Reason
383		if reason == "" {
384			reason = http.StatusText(ex.Status)
385		}
386		b.WriteString("\n" + strings.TrimSpace(fmt.Sprintf("%s %d %s", httpVersion, ex.Status, reason)) + "\n")
387		writeHeaders(b, ex.Header, responseOrder)
388		b.WriteString("\n")
389		if ex.Stub != "" {
390			b.WriteString(ex.Stub)
391		} else {
392			b.Write(ex.Body)
393		}
394		b.WriteString("\n")
395	}
396	
397	// writeHeaders writes the headers in a fixed order (the preferred names first,
398	// then the others sorted) so that a regeneration does not reshuffle a file.
399	func writeHeaders(b *bytes.Buffer, h http.Header, preferred []string, skip ...string) {
400		skipped := map[string]bool{}
401		for _, s := range skip {
402			skipped[s] = true
403		}
404		var names []string
405		for _, p := range preferred {
406			if _, ok := h[p]; ok && !skipped[p] {
407				names = append(names, p)
408			}
409		}
410		var others []string
411		for k := range h {
412			if skipped[k] || contains(preferred, k) {
413				continue
414			}
415			others = append(others, k)
416		}
417		sort.Strings(others)
418		for _, name := range append(names, others...) {
419			display := name
420			if d, ok := displayNames[name]; ok {
421				display = d
422			}
423			for _, v := range h[name] {
424				fmt.Fprintf(b, "%s: %s\n", display, v)
425			}
426		}
427	}
428	
429	func contains(list []string, s string) bool {
430		for _, v := range list {
431			if v == s {
432				return true
433			}
434		}
435		return false
436	}
