1	package nexusfixture
2	
3	import (
4		"embed"
5		"fmt"
6		"io/fs"
7		"path"
8		"path/filepath"
9		"runtime"
10		"sort"
11		"strings"
12	)
13	
14	//go:embed fixtures
15	var embedded embed.FS
16	
17	const fixturesDir = "fixtures"
18	
19	// evidenceDirs maps a campaign to the dated measurement it was imported from,
20	// relative to the repository root.
21	var evidenceDirs = map[string]string{
22		"catalog": "docs/measurements/nexus-catalog",
23	}
24	
25	// Load reads the fixtures of one embedded campaign, sorted by name. It refuses
26	// a pending fixture: a request without an answer cannot be replayed.
27	func Load(campaign string) ([]Fixture, error) {
28		sub, err := fs.Sub(embedded, fixturesDir)
29		if err != nil {
30			return nil, fmt.Errorf("nexusfixture: %w", err)
31		}
32		return LoadFS(sub, campaign)
33	}
34	
35	// LoadFS is Load over any file system: it reads <campaign>/*.http from fsys.
36	func LoadFS(fsys fs.FS, campaign string) ([]Fixture, error) {
37		entries, err := fs.ReadDir(fsys, campaign)
38		if err != nil {
39			return nil, fmt.Errorf("nexusfixture: campaign %q: %w", campaign, err)
40		}
41		var fixtures []Fixture
42		for _, e := range entries {
43			if e.IsDir() || !strings.HasSuffix(e.Name(), fileSuffix) {
44				continue
45			}
46			data, err := fs.ReadFile(fsys, path.Join(campaign, e.Name()))
47			if err != nil {
48				return nil, fmt.Errorf("nexusfixture: campaign %q: %w", campaign, err)
49			}
50			f, err := Parse(campaign, e.Name(), data)
51			if err != nil {
52				return nil, err
53			}
54			if f.Meta.Record == RecordPending {
55				return nil, fmt.Errorf("nexusfixture: %s is pending (no recorded answer): run the recorder first", f.Name)
56			}
57			fixtures = append(fixtures, f)
58		}
59		sort.Slice(fixtures, func(i, j int) bool { return fixtures[i].Name < fixtures[j].Name })
60		return fixtures, nil
61	}
62	
63	// Campaigns lists the embedded campaigns, sorted.
64	func Campaigns() []string {
65		entries, err := fs.ReadDir(embedded, fixturesDir)
66		if err != nil {
67			return nil
68		}
69		var names []string
70		for _, e := range entries {
71			if e.IsDir() {
72				names = append(names, e.Name())
73			}
74		}
75		sort.Strings(names)
76		return names
77	}
78	
79	// All loads every embedded campaign.
80	func All() ([]Fixture, error) {
81		var all []Fixture
82		for _, c := range Campaigns() {
83			fixtures, err := Load(c)
84			if err != nil {
85				return nil, err
86			}
87			all = append(all, fixtures...)
88		}
89		return all, nil
90	}
91	
92	// EvidenceDir is the directory under docs/measurements/ whose files a
93	// campaign's unrecorded fixtures are byte-identical to.
94	func EvidenceDir(campaign string) (string, bool) {
95		dir, ok := evidenceDirs[campaign]
96		return dir, ok
97	}
98	
99	// SourceDir is the fixtures directory in the source tree, for the recorder
100	// (the embedded copy is read-only).
101	func SourceDir() (string, error) {
102		_, file, _, ok := runtime.Caller(0)
103		if !ok {
104			return "", fmt.Errorf("nexusfixture: cannot locate the source tree")
105		}
106		return filepath.Join(filepath.Dir(file), fixturesDir), nil
107	}
