390	// Every embedded NX-03 file must come back byte for byte, so that the recorder
391	// (which writes with Format) produces the same format as the imported files.
392	// Response headers live in an http.Header (a map): Format fixes their order,
393	// which must be Server, Docker-Distribution-Api-Version, WWW-Authenticate,
394	// Content-Type, Content-Length (the order of every NX-03 file), and writes
395	// WWW-Authenticate with its capitals, not as the canonical Www-Authenticate.
396	func TestEveryFixtureRoundTrips(t *testing.T) {
397		files, err := filepath.Glob(filepath.Join("fixtures", "catalog", "*.http"))
398		if err != nil || len(files) != 30 {
399			t.Fatalf("fixtures/catalog holds %d .http files (err %v), want the 30 of the plan", len(files), err)
400		}
401		for _, path := range files {
402			name := strings.TrimSuffix(filepath.Base(path), ".http")
403			t.Run(name, func(t *testing.T) {
404				data, err := os.ReadFile(path)
405				if err != nil {
406					t.Fatal(err)
407				}
408				f, err := nexusfixture.Parse("catalog", filepath.Base(path), data)
409				if err != nil {
410					t.Fatalf("Parse: %v", err)
411				}
412				if got := nexusfixture.Format(f); !bytes.Equal(got, data) {
413					t.Errorf("Format(Parse(b)) != b\n--- want\n%s\n--- got\n%s", data, got)
414				}
415			})
416		}
417	}
