94	func TestLoadedFixturesCarryTheMeasuredFacts(t *testing.T) {
95		// Facts the replay tests of the next steps stand on, read here once on the
96		// loaded set (a regeneration that changed one must be seen).
97		byName := map[string]nexusfixture.Fixture{}
98		fixtures, err := nexusfixture.Load("catalog")
99		if err != nil {
100			t.Fatalf("Load(catalog): %v", err)
101		}
102		for _, f := range fixtures {
103			byName[f.Name] = f
104		}
105		tests := []struct {
106			name       string
107			wantStatus int
108			wantHost   string
109		}{
110			{"rest-repositories-group-docker-group--admin", 200, "127.0.0.1:30481"},
111			{"rest-repositories-group-docker-group--pull", 404, "127.0.0.1:30481"}, // contradiction C1: not 403
112			{"rest-repositories-group-docker-group--anon", 403, "127.0.0.1:30481"},
113			{"catalog-group-connector-30482--admin", 200, "127.0.0.1:30482"},
114			{"catalog-hosted-root-30481--admin", 404, "127.0.0.1:30481"}, // no shared host catalog (IS-07)
115			{"v2-ping-30481--anon", 401, "127.0.0.1:30481"},
116			{"v2-ping-30482--anon", 401, "127.0.0.1:30482"},
117		}
118		for _, tt := range tests {
119			t.Run(tt.name, func(t *testing.T) {
120				f, ok := byName[tt.name]
121				if !ok {
122					t.Fatalf("%s is not loaded", tt.name)
123				}
124				ex := f.Exchanges[0]
125				if ex.Status != tt.wantStatus {
126					t.Errorf("Status = %d, want %d", ex.Status, tt.wantStatus)
127				}
128				if ex.Host != tt.wantHost {
129					t.Errorf("Host = %q, want %q", ex.Host, tt.wantHost)
130				}
131			})
132		}
133		ping := byName["v2-ping-30482--anon"].Exchanges[0]
134		if got := ping.Header.Get("WWW-Authenticate"); !strings.HasPrefix(got, `Bearer realm="http://127.0.0.1:30482/v2/token"`) {
135			t.Errorf("ping WWW-Authenticate = %q, want the Bearer challenge as recorded", got)
136		}
137		// Pinned for the fake server's catalog tolerance (step 3): the DevDesk-shaped
138		// ?n=1000 page and the no-n recording are the same answer on the group connector.
139		n1000 := byName["page-group-n1000--admin"].Exchanges[0]
140		plain := byName["catalog-group-connector-30482--admin"].Exchanges[0]
141		if n1000.Target != "/v2/_catalog?n=1000" || plain.Target != "/v2/_catalog" {
142			t.Errorf("targets = %q and %q, want /v2/_catalog?n=1000 and /v2/_catalog", n1000.Target, plain.Target)
143		}
144	}
