248					t.Fatalf("%s: neither recorded-by nexus-bench record nor backed by its evidence: %v", f.Name, err)
249				}
250				if got := nexusfixture.Format(f); string(got) != string(want) {
251					t.Errorf("%s is not byte-identical to %s/%s.http and is not recorded-by nexus-bench record", f.Name, evidence, f.Name)
252				}
253			})
